func TestRender(t *testing.T) {
	id := createMarket(alice, "Render shows me?", now+day, now)
	placeBet(alice, id, true, 100, now)
	placeBet(bob, id, false, 300, now)
	out := Render("")
	if !strings.Contains(out, "Render shows me?") {
		t.Fatal("Render output is missing the market question")
	}
	if !strings.Contains(out, "#"+strconv.Itoa(id)) {
		t.Fatal("Render output is missing the market id")
	}
	if !strings.Contains(out, "0.000100 GNOT") {
		t.Fatalf("Render output is missing the YES pool amount; got:\n%s", out)
	}
	if !strings.Contains(out, "0.000300 GNOT") {
		t.Fatalf("Render output is missing the NO pool amount; got:\n%s", out)
	}
	if !strings.Contains(out, "open") {
		t.Fatal("Render output should mark the market open")
	}
}

// Package dice holds the pure math behind Tavern Dice: deriving a dice
// roll from seed bytes and computing payouts. It keeps no state, so it is
// a package (p/), not a realm. All functions are deterministic and safe
// to unit test without any chain context.
package dice

import (
	"crypto/sha256"
	"encoding/binary"
	"math/overflow"
)

// RollFromSeed derives a dice roll in [1, 6] from arbitrary seed bytes.
// The seed is hashed with SHA-256 and the first 8 bytes are taken modulo 6.
// Uniformity: 2^64 mod 6 leaves a negligible bias (~1e-19), fine for a game.
func RollFromSeed(seed []byte) int {
	h := sha256.Sum256(seed)
	v := binary.BigEndian.Uint64(h[:8])
	return int(v%6) + 1
}

// NumberPayout returns the total payout (stake included) for a winning
// single-number bet: 5x the stake. Fair odds for a 1-in-6 guess would be
// 6x, so the house edge is 1/6 (~16.7%).
func NumberPayout(bet int64) int64 {
	p, ok := overflow.Mul64(bet, 5)
	if !ok {
		panic("payout overflow")
	}
	return p
}

// ParityPayout returns the total payout (stake included) for a winning
// odd/even bet: 1.9x the stake (bet*19/10). Fair odds would be 2x, so
// the house edge is 5%.
func ParityPayout(bet int64) int64 {
	p, ok := overflow.Mul64(bet, 19)
	if !ok {
		panic("payout overflow")
	}
	return p / 10
}

// MaxNumberBet caps a single-number bet so that the worst-case payout
// (5x the stake) never exceeds a quarter of the bankroll.
func MaxNumberBet(bankroll int64) int64 {
	if bankroll <= 0 {
		return 0
	}
	return bankroll / 20
}

// MaxParityBet caps an odd/even bet so that the worst-case payout
// (1.9x the stake) never exceeds a quarter of the bankroll.
func MaxParityBet(bankroll int64) int64 {
	if bankroll <= 0 {
		return 0
	}
	return bankroll / 8
}

package dice

import (
	"strconv"
	"testing"
)

func TestRollFromSeedRange(t *testing.T) {
	// 1000 different seeds: every roll must be in [1, 6] and every face
	// must show up (a rough uniformity sanity check).
	seen := map[int]bool{}
	for i := 0; i < 1000; i++ {
		seed := []byte("tavern-dice-seed-" + strconv.Itoa(i))
		roll := RollFromSeed(seed)
		if roll < 1 || roll > 6 {
			t.Fatalf("roll %d out of range for seed %d", roll, i)
		}
		seen[roll] = true
	}
	if len(seen) != 6 {
		t.Fatalf("expected all 6 faces in 1000 rolls, got %d", len(seen))
	}
	// Deterministic: same seed, same roll.
	a := RollFromSeed([]byte("same-seed"))
	b := RollFromSeed([]byte("same-seed"))
	if a != b {
		t.Fatalf("same seed gave different rolls: %d vs %d", a, b)
	}
}

func TestNumberPayout(t *testing.T) {
	if got := NumberPayout(1000); got != 5000 {
		t.Fatalf("NumberPayout(1000) = %d, want 5000", got)
	}
	if got := NumberPayout(0); got != 0 {
		t.Fatalf("NumberPayout(0) = %d, want 0", got)
	}
	if got := NumberPayout(200000); got != 1000000 {
		t.Fatalf("NumberPayout(200000) = %d, want 1000000", got)
	}
}

func TestParityPayout(t *testing.T) {
	if got := ParityPayout(1000); got != 1900 {
		t.Fatalf("ParityPayout(1000) = %d, want 1900", got)
	}
	if got := ParityPayout(1005); got != 1909 {
		// 1005*19/10 = 1909 (integer division truncates).
		t.Fatalf("ParityPayout(1005) = %d, want 1909", got)
	}
	if got := ParityPayout(0); got != 0 {
		t.Fatalf("ParityPayout(0) = %d, want 0", got)
	}
}

func TestMaxBets(t *testing.T) {
	// Bankroll 1,000,000ugnot: number max 50,000 (payout 250,000 = 1/4),
	// parity max 125,000 (payout 237,500 < 1/4).
	if got := MaxNumberBet(1000000); got != 50000 {
		t.Fatalf("MaxNumberBet(1000000) = %d, want 50000", got)
	}
	if got := MaxParityBet(1000000); got != 125000 {
		t.Fatalf("MaxParityBet(1000000) = %d, want 125000", got)
	}
	// Empty bankroll: no bets allowed.
	if got := MaxNumberBet(0); got != 0 {
		t.Fatalf("MaxNumberBet(0) = %d, want 0", got)
	}
	if got := MaxParityBet(-5); got != 0 {
		t.Fatalf("MaxParityBet(-5) = %d, want 0", got)
	}
	// Solvency: worst-case payouts never exceed a quarter of the bankroll.
	bankroll := int64(1000000)
	if NumberPayout(MaxNumberBet(bankroll)) > bankroll/4 {
		t.Fatalf("number max payout exceeds bankroll/4")
	}
	if ParityPayout(MaxParityBet(bankroll)) > bankroll/4 {
		t.Fatalf("parity max payout exceeds bankroll/4")
	}
}

package tavern_dice

import (
	"strconv"
)

// Render renders the realm for gnoweb. The home page shows the bankroll,
// how to play, recent rolls, and the leaderboard. "/rolls" shows the same
// recent-rolls table on its own. Only bech32 addresses and numbers are
// ever embedded in the output; no user-supplied text is rendered.
func Render(path string) string {
	if path == "rolls" {
		return "# Tavern Dice — Recent Rolls\n\n" + rollsTable() + "\n\n[Back home](.)"
	}
	out := "# 🎲 Tavern Dice\n\n"
	out += "A tiny on-chain dice game. Bet testnet ugnot, roll the dice, " +
		"get paid in the same transaction.\n\n"
	out += "## Bankroll\n\n"
	out += "- **Bankroll:** " + formatAmount(Bankroll()) + "\n"
	out += "- **Minimum bet:** " + formatAmount(minBet) + "\n"
	out += "- **Owner:** " + shortAddr(owner) + "\n\n"
	out += "## How to play\n\n"
	out += "1. Fund the bankroll first if it is empty " +
		"(`Fund` with `-send <amount>ugnot`).\n"
	out += "2. Bet on a number: `BetNumber` with `-send <amount>ugnot`, " +
		"number 1-6. Win pays **5x**.\n"
	out += "3. Or bet odd/even: `BetParity` with `-send <amount>ugnot`. " +
		"Win pays **1.9x**.\n"
	out += "4. The worst-case payout of a single bet is capped at a quarter " +
		"of the bankroll, so the house can always pay.\n\n"
	out += "## Totals\n\n"
	out += "- Bets settled: " + strconv.FormatInt(totalBets, 10) + "\n"
	out += "- Total wagered: " + formatAmount(totalWagered) + "\n"
	out += "- Total paid out: " + formatAmount(totalPaidOut) + "\n"
	out += "- Wins: " + strconv.FormatInt(totalWins, 10) + "\n\n"
	out += "## Recent rolls\n\n" + rollsTable() + "\n\n"
	out += "## Leaderboard (biggest single win)\n\n" + leaderboard() + "\n"
	return out
}

func rollsTable() string {
	if len(rolls) == 0 {
		return "No bets yet. Be the first to roll.\n"
	}
	out := "| # | Player | Bet | Choice | Roll | Payout |\n"
	out += "|---|--------|-----|--------|------|--------|\n"
	for i := len(rolls) - 1; i >= 0; i-- {
		r := rolls[i]
		out += "| " + strconv.FormatInt(r.seq, 10) +
			" | " + shortAddr(r.player) +
			" | " + formatAmount(r.bet) +
			" | " + r.choice +
			" | **" + strconv.Itoa(r.roll) + "**" +
			" | " + formatAmount(r.payout) + " |\n"
	}
	return out
}

func leaderboard() string {
	type entry struct {
		player address
		win    int64
		bets   int64
		wins   int64
	}
	top := []entry{}
	for addr, st := range players {
		if st.biggestWin <= 0 {
			continue
		}
		e := entry{player: addr, win: st.biggestWin, bets: st.bets, wins: st.wins}
		// Insertion sort, biggest first, keep at most 5.
		pos := len(top)
		for pos > 0 && top[pos-1].win < e.win {
			pos--
		}
		top = append(top, entry{})
		copy(top[pos+1:], top[pos:])
		top[pos] = e
		if len(top) > 5 {
			top = top[:5]
		}
	}
	if len(top) == 0 {
		return "No winners yet.\n"
	}
	out := "| # | Player | Biggest win | Bets | Wins |\n"
	out += "|---|--------|-------------|------|------|\n"
	for i, e := range top {
		out += "| " + strconv.Itoa(i+1) +
			" | " + shortAddr(e.player) +
			" | " + formatAmount(e.win) +
			" | " + strconv.FormatInt(e.bets, 10) +
			" | " + strconv.FormatInt(e.wins, 10) + " |\n"
	}
	return out
}

// formatAmount renders an ugnot amount with its unit.
func formatAmount(amount int64) string {
	return strconv.FormatInt(amount, 10) + " ugnot"
}

// shortAddr shortens a bech32 address for display.
func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 14 {
		return s
	}
	return s[:10] + "…" + s[len(s)-4:]
}

// Package tavern-dice implements Tavern Dice, a small on-chain dice game
// on Gno.land.
//
// How it works:
//   - Anyone funds the bankroll with Fund() (native ugnot, testnet only).
//   - Players bet with BetNumber() (pick 1-6, win pays 5x) or BetParity()
//     (pick odd/even, win pays 1.9x). The bet is sent with the transaction
//     (-send <amount>ugnot); winnings are paid out in the same transaction.
//   - The roll is derived from public chain data (block height, block time,
//     roll sequence, caller address, previous roll hash) hashed with SHA-256.
//     It is unpredictable to a player before their transaction lands, but a
//     block proposer could theoretically influence it. This is demo-grade
//     randomness for testnet play money, not for real stakes.
//   - The worst-case payout of any single bet is capped at a quarter of the
//     bankroll, so the house can always pay.
//
// Security notes (see docs/resources/gno-security-guide.md):
//   - Every function that takes payment guards with cur.Previous().IsUserCall()
//     AND checks unsafe.OriginSend() — the pair, never one alone. IsUser()
//     would also accept user-run ephemeral realms (maketx run), which can
//     consume the origin-send envelope before calling us.
//   - Balances are read with banker.GetCoin (single denom), never
//     GetCoins().AmountOf on a caller-supplied address.
//   - No user-supplied free text is ever rendered; only bech32 addresses
//     and numbers appear in Render output.
package tavern_dice

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"crypto/sha256"
	"encoding/binary"
	"strconv"
	"time"

	"gno.land/p/g1pekk0w02cyd22l339fqe5j2h2d5zffm7kyn8cq/dice/v0"
)

// On-chain path of this realm. Used by the read-only view functions to
// resolve the realm's own address.
const pkgPath = "gno.land/r/g1pekk0w02cyd22l339fqe5j2h2d5zffm7kyn8cq/tavern_dice"

const (
	// minBet is the smallest accepted bet, in ugnot (0.001 GNOT).
	minBet int64 = 1000
	// maxHistory is how many recent rolls are kept on chain.
	maxHistory = 20
	// denom is the only accepted coin.
	denom = "ugnot"
)

var (
	// owner is the deployer. Set in init; only the owner can Withdraw.
	owner address
	// rollSeq counts every settled bet; it feeds the roll derivation.
	rollSeq int64
	// prevRollHash chains rolls together so no two rolls share a seed.
	prevRollHash [32]byte

	totalBets    int64
	totalWagered int64
	totalPaidOut int64
	totalWins    int64

	rolls   []rollRecord
	players map[address]*playerStats
	funders map[address]int64
)

// rollRecord is one settled bet, kept for the recent-rolls table.
type rollRecord struct {
	seq    int64
	player address
	kind   string // "number" or "parity"
	choice string // e.g. "4", "odd", "even"
	roll   int
	bet    int64
	payout int64
}

// playerStats aggregates one address's play.
type playerStats struct {
	bets       int64
	wins       int64
	wagered    int64
	biggestWin int64
}

func init(cur realm) {
	// The deployer is the owner. In unit tests init runs under a test
	// realm, so only claim ownership for a direct user call.
	if cur.Previous().IsUserCall() {
		owner = cur.Previous().Address()
	}
	if players == nil {
		players = map[address]*playerStats{}
	}
	if funders == nil {
		funders = map[address]int64{}
	}
}

// Fund adds native ugnot to the bankroll. Anyone can fund; funders are
// recorded for transparency.
func Fund(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("funding must come directly from a user account")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != denom {
		panic("fund with ugnot only")
	}
	amount := sent[0].Amount
	if amount <= 0 {
		panic("fund amount must be positive")
	}
	caller := cur.Previous().Address()
	funders[caller] += amount
	chain.Emit("BankrollFunded", "funder", caller.String(), "amount", strconv.FormatInt(amount, 10))
}

// BetNumber bets on a single number (1-6). Win pays 5x the stake.
// The bet is the ugnot sent with the transaction (-send <amount>ugnot).
// Returns the roll.
func BetNumber(cur realm, number int) int {
	if number < 1 || number > 6 {
		panic("number must be between 1 and 6")
	}
	bet := betAmount(cur)
	roll, _ := placeBet(cur, "number", strconv.Itoa(number), bet, dice.NumberPayout(bet), func(roll int) bool {
		return roll == number
	})
	return roll
}

// BetParity bets on odd/even. Win pays 1.9x the stake.
// The bet is the ugnot sent with the transaction (-send <amount>ugnot).
// Returns the roll.
func BetParity(cur realm, even bool) int {
	choice := "odd"
	if even {
		choice = "even"
	}
	bet := betAmount(cur)
	roll, _ := placeBet(cur, "parity", choice, bet, dice.ParityPayout(bet), func(roll int) bool {
		return (roll%2 == 0) == even
	})
	return roll
}

// Withdraw moves bankroll funds to the owner (deployer). The owner can
// withdraw any amount up to the current bankroll.
func Withdraw(cur realm, amount int64) {
	caller := cur.Previous().Address()
	if caller != owner {
		panic("only the owner can withdraw")
	}
	if amount <= 0 {
		panic("amount must be positive")
	}
	bankroll := realmBankroll()
	if amount > bankroll {
		panic("amount exceeds bankroll")
	}
	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(
		cur.Address(), owner, chain.Coins{{Denom: denom, Amount: amount}},
	)
	chain.Emit("BankrollWithdrawn", "owner", owner.String(), "amount", strconv.FormatInt(amount, 10))
}

// Owner returns the deployer address.
func Owner() address {
	return owner
}

// MinBet returns the smallest accepted bet in ugnot.
func MinBet() int64 {
	return minBet
}

// Bankroll returns the realm's current ugnot balance.
func Bankroll() int64 {
	return banker.NewReadonlyBanker().GetCoin(chain.PackageAddress(pkgPath), denom)
}

// Stats returns total bets, total wagered, total paid out, total wins.
func Stats() (bets, wagered, paidOut, wins int64) {
	return totalBets, totalWagered, totalPaidOut, totalWins
}

// betAmount reads the bet from the origin-send envelope. It does NOT
// trust any function argument for the amount: the coins actually sent
// are the bet. The IsUserCall guard and the OriginSend check belong
// together: without the guard, an intermediate realm could fake the
// envelope; without the amount check, a user could bet nothing.
func betAmount(cur realm) int64 {
	if !cur.Previous().IsUserCall() {
		panic("bets must be placed directly by a user account")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != denom {
		panic("bet must be sent in ugnot only")
	}
	bet := sent[0].Amount
	if bet < minBet {
		panic("bet below minimum")
	}
	return bet
}

// placeBet settles one bet: derives the roll, pays out on a win, and
// records the result. bet is the amount actually sent (validated by the
// caller via betAmount); payoutIfWin is the total payout (stake included)
// the player receives on a win. The solvency check caps the worst-case
// payout at a quarter of the bankroll (which already includes this bet,
// since the sent coins landed before the function ran).
func placeBet(cur realm, kind, choice string, bet, payoutIfWin int64, won func(int) bool) (int, int64) {
	bankroll := realmBankroll()
	if payoutIfWin > bankroll/4 {
		panic("bet too large for the bankroll")
	}
	caller := cur.Previous().Address()
	roll, seedHash := deriveRoll(caller)
	payout := int64(0)
	if won(roll) {
		payout = payoutIfWin
		banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(
			cur.Address(), caller, chain.Coins{{Denom: denom, Amount: payout}},
		)
	}
	recordRoll(caller, kind, choice, roll, bet, payout, seedHash)
	chain.Emit("BetSettled",
		"player", caller.String(),
		"kind", kind,
		"choice", choice,
		"roll", strconv.Itoa(roll),
		"bet", strconv.FormatInt(bet, 10),
		"payout", strconv.FormatInt(payout, 10),
	)
	return roll, payout
}

// deriveRoll derives the next roll from public chain data. It returns the
// roll (1-6) and the seed hash, which chains into the next roll.
func deriveRoll(caller address) (int, [32]byte) {
	var material []byte
	var b [8]byte
	binary.BigEndian.PutUint64(b[:], uint64(runtime.ChainHeight()))
	material = append(material, b[:]...)
	binary.BigEndian.PutUint64(b[:], uint64(time.Now().UnixNano()))
	material = append(material, b[:]...)
	binary.BigEndian.PutUint64(b[:], uint64(rollSeq))
	material = append(material, b[:]...)
	material = append(material, []byte(caller.String())...)
	material = append(material, prevRollHash[:]...)
	seed := sha256.Sum256(material)
	return dice.RollFromSeed(seed[:]), sha256.Sum256(seed[:])
}

// recordRoll appends a settled bet to history (capped) and updates stats.
func recordRoll(caller address, kind, choice string, roll int, bet, payout int64, seedHash [32]byte) {
	totalBets++
	totalWagered += bet
	if payout > 0 {
		totalWins++
		totalPaidOut += payout
	}
	st := players[caller]
	if st == nil {
		st = &playerStats{}
		players[caller] = st
	}
	st.bets++
	st.wagered += bet
	if payout > 0 {
		st.wins++
		if payout > st.biggestWin {
			st.biggestWin = payout
		}
	}
	rolls = append(rolls, rollRecord{
		seq: rollSeq, player: caller, kind: kind, choice: choice,
		roll: roll, bet: bet, payout: payout,
	})
	if len(rolls) > maxHistory {
		// Drop the oldest entry; copy so the backing array does not grow.
		kept := make([]rollRecord, 0, maxHistory)
		kept = append(kept, rolls[len(rolls)-maxHistory:]...)
		rolls = kept
	}
	rollSeq++
	prevRollHash = seedHash
}

// realmBankroll reads the realm's own ugnot balance (single denom read).
func realmBankroll() int64 {
	return banker.NewReadonlyBanker().GetCoin(chain.PackageAddress(pkgPath), denom)
}

package tavern_dice

import (
	"chain"
	"chain/banker"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

func bankerNewReadonly() banker.Banker {
	return banker.NewReadonlyBanker()
}

func resetTestState() {
	owner = address("")
	rollSeq = 0
	prevRollHash = [32]byte{}
	totalBets = 0
	totalWagered = 0
	totalPaidOut = 0
	totalWins = 0
	rolls = nil
	players = map[address]*playerStats{}
	funders = map[address]int64{}
}

func pkgAddr() address {
	return chain.PackageAddress(pkgPath)
}

// betAs places one number bet as player with the given send amount.
// The caller must have issued coins to the realm (bankroll) first.
func betAs(cur realm, t *testing.T, player address, amount int64, number int) int {
	testing.SetRealm(testing.NewUserRealm(player))
	testing.SetOriginSend(chain.Coins{{Denom: denom, Amount: amount}})
	return BetNumber(cross(cur), number)
}

func TestBetNumberWin(cur realm, t *testing.T) {
	defer resetTestState()
	testing.IssueCoins(pkgAddr(), chain.Coins{{Denom: denom, Amount: 10000000}})
	player := testutils.TestAddress("player1")

	// The roll is deterministic in tests (fixed block height/time), so we
	// can pre-compute it and bet on it.
	expectedRoll, _ := deriveRoll(player)
	roll := betAs(cur, t, player, 10000, expectedRoll)
	uassert.Equal(t, expectedRoll, roll)
	uassert.Equal(t, int64(1), totalBets)
	uassert.Equal(t, int64(10000), totalWagered)
	uassert.Equal(t, int64(50000), totalPaidOut)
	uassert.Equal(t, int64(1), totalWins)
	uassert.Equal(t, int64(50000), players[player].biggestWin)
	// Payout landed on the player; the bankroll paid it out.
	banker_ := bankerNewReadonly()
	uassert.Equal(t, int64(50000), banker_.GetCoin(player, denom))
	uassert.Equal(t, int64(10000000-50000), banker_.GetCoin(pkgAddr(), denom))
}

func TestBetNumberLoss(cur realm, t *testing.T) {
	defer resetTestState()
	testing.IssueCoins(pkgAddr(), chain.Coins{{Denom: denom, Amount: 10000000}})
	player := testutils.TestAddress("player2")

	expectedRoll, _ := deriveRoll(player)
	losing := expectedRoll%6 + 1 // a number the roll cannot be
	roll := betAs(cur, t, player, 10000, losing)
	uassert.Equal(t, expectedRoll, roll)
	uassert.Equal(t, int64(1), totalBets)
	uassert.Equal(t, int64(10000), totalWagered)
	uassert.Equal(t, int64(0), totalPaidOut)
	uassert.Equal(t, int64(0), totalWins)
	uassert.Equal(t, int64(0), players[player].biggestWin)
	uassert.Equal(t, 1, len(rolls))
	uassert.Equal(t, int64(0), rolls[0].payout)
}

func TestBetParityWinAndLoss(cur realm, t *testing.T) {
	defer resetTestState()
	testing.IssueCoins(pkgAddr(), chain.Coins{{Denom: denom, Amount: 10000000}})
	player := testutils.TestAddress("player3")

	expectedRoll, _ := deriveRoll(player)
	even := expectedRoll%2 == 0
	testing.SetRealm(testing.NewUserRealm(player))
	testing.SetOriginSend(chain.Coins{{Denom: denom, Amount: 10000}})
	roll := BetParity(cross(cur), even)
	uassert.Equal(t, expectedRoll, roll)
	uassert.Equal(t, int64(19000), totalPaidOut) // 1.9x

	// Second bet, wrong parity: no payout.
	testing.SetRealm(testing.NewUserRealm(player))
	testing.SetOriginSend(chain.Coins{{Denom: denom, Amount: 10000}})
	BetParity(cross(cur), !even)
	uassert.Equal(t, int64(2), totalBets)
	uassert.Equal(t, int64(19000), totalPaidOut)
	uassert.Equal(t, int64(1), totalWins)
}

func TestBetBelowMin(cur realm, t *testing.T) {
	defer resetTestState()
	testing.IssueCoins(pkgAddr(), chain.Coins{{Denom: denom, Amount: 10000000}})
	player := testutils.TestAddress("player4")
	testing.SetRealm(testing.NewUserRealm(player))
