func TestWithdraw(cur realm, t *testing.T) {
	defer resetTestState()
	testing.IssueCoins(pkgAddr(), chain.Coins{{Denom: denom, Amount: 10000000}})
	ownerAddr := testutils.TestAddress("owner1")
